function HoverPiecesProviderInner({ store, children }: { store: DesignStore; children: ReactNode }) {
  const actor = useSketchpadActorSafe();
  const kitScope = useKitScope();
  const designScope = useDesignScope();
  const syncKey = `${kitScope?.guid ?? ""}:${designScope?.guid ?? ""}`;
  const lastResultRef = useRef<HoverPiecesContextValue>(EMPTY_HOVER_CONTEXT);
  const [hoverData, setHoverData] = useState<HoverPiecesContextValue>(EMPTY_HOVER_CONTEXT);

  useEffect(() => {
    const recompute = () => {
      const hoverFromActor = actor?.getSnapshot().context.designApps[syncKey]?.hover;
      const hoverFromStore = store.snapshot().hover;
      const hover = hoverFromActor ?? hoverFromStore;
      const result = computeHoverData(store, { hover } as DesignAppState);
      if (areHoverContextsEqual(result, lastResultRef.current)) return;
      lastResultRef.current = result;
      setHoverData(result);
    };
    recompute();
    const unsubStore = store.subscribe(recompute);
    const actorSub = actor?.subscribe(recompute);
    return () => {
      unsubStore();
      actorSub?.unsubscribe();
    };
  }, [store, actor, syncKey]);

  return <HoverPiecesContext.Provider value={hoverData}>{children}</HoverPiecesContext.Provider>;
}

