const materialColor = useMemo(() => {
  // Fast path: CSS variable-based fills can be resolved without DOM manipulation
  if (fill === "transparent") return foregroundColor;
  if (fill.startsWith("rgb")) return fill;
  // Cache DOM element for CSS variable resolution to avoid repeated DOM creation
  if (!resolveColorCacheDiv) {
    resolveColorCacheDiv = document.createElement("div");
    resolveColorCacheDiv.style.position = "absolute";
    resolveColorCacheDiv.style.visibility = "hidden";
    resolveColorCacheDiv.style.pointerEvents = "none";
    resolveColorCacheDiv.style.width = "0";
    resolveColorCacheDiv.style.height = "0";
    document.body.appendChild(resolveColorCacheDiv);
  }
  const cachedResult = resolveColorCache.get(fill);
  if (cachedResult !== undefined) return cachedResult;

  resolveColorCacheDiv.style.color = fill;
  const computedColor = getComputedStyle(resolveColorCacheDiv).color;

  if (!resolveColorCacheCanvas) {
    resolveColorCacheCanvas = document.createElement("canvas");
    resolveColorCacheCanvas.width = 1;
    resolveColorCacheCanvas.height = 1;
  }
  const ctx = resolveColorCacheCanvas.getContext("2d");
  if (!ctx) { resolveColorCache.set(fill, computedColor); return computedColor; }

  ctx.clearRect(0, 0, 1, 1);
  ctx.fillStyle = computedColor;
  ctx.fillRect(0, 0, 1, 1);
  const imageData = ctx.getImageData(0, 0, 1, 1);
  const [r, g, b, a] = imageData.data;

  const result = a === 0 ? foregroundColor : `rgb(${r}, ${g}, ${b})`;
  resolveColorCache.set(fill, result);
  return result;
}, [fill, foregroundColor]);

